css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; perspective: 600px; }
.loader span { position: absolute; inset: 16%; border-radius: 50%; transform-style: preserve-3d; animation: coin calc(var(--loader-speed) * 1.6) linear infinite; }
.loader span::before, .loader span::after { content: ''; position: absolute; inset: 0; border-radius: 50%; backface-visibility: hidden; }
.loader span::before { background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent)); }
.loader span::after { background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); transform: rotateY(180deg); }
@keyframes coin { to { transform: rotateY(360deg); } }
